	(2102, 144, 'banner_page_background', 'a:5:{s:3:"url";s:71:"https://crsdsenegal.test/wp-content/uploads/2025/03/IMG_9208-scaled.jpg";s:2:"id";s:2:"99";s:6:"height";s:4:"1707";s:5:"width";s:4:"2560";s:9:"thumbnail";s:72:"https://crsdsenegal.test/wp-content/uploads/2025/03/IMG_9208-150x150.jpg";}'),
